package school.magiccodex.paper;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.sql.*;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class ArtifactOwnershipStoreTest {
 String url;ArtifactOwnershipStore school,wild;UUID player=UUID.randomUUID();@TempDir Path temp;
 @BeforeEach void setup()throws Exception{url="jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000";school=new ArtifactOwnershipStore(()->DriverManager.getConnection(url));wild=new ArtifactOwnershipStore(()->DriverManager.getConnection(url));school.initialize();}
 @AfterEach void close()throws Exception{try(var c=DriverManager.getConnection(url);var s=c.createStatement()){s.execute("SHUTDOWN");}}
 String op(){return UUID.randomUUID().toString();}
 List<ArtifactOwnershipStore.Choice> choices(String... ids){return Arrays.stream(ids).map(id->new ArtifactOwnershipStore.Choice(id,0,2)).toList();}
 @Test void schoolOwnershipVisibleOnWildAndReconnect()throws Exception{school.purchase(op(),player,choices("test"),"item:shard");assertEquals(Set.of("test"),wild.owned(player));var reconnect=new ArtifactOwnershipStore(()->DriverManager.getConnection(url));assertEquals(Set.of("test"),reconnect.owned(player));}
 @Test void concurrentServersGrantOnceAndCompensateAllDuplicates()throws Exception{try(var pool=Executors.newFixedThreadPool(6)){var work=new ArrayList<Callable<Boolean>>();for(int i=0;i<12;i++){var store=i%2==0?school:wild;work.add(()->store.purchase(op(),player,choices("test"),"item:shard").getFirst().fresh());}int fresh=0;for(var f:pool.invokeAll(work))if(f.get())fresh++;assertEquals(1,fresh);assertEquals(11,school.pendingDeliveries().size());}}
 @Test void duplicateInsideFivePullAndAcrossServersUsesSharedAuthority()throws Exception{var first=school.purchase(op(),player,choices("test","test","other","test","other"),"item:shard");assertEquals(List.of(true,false,true,false,false),first.stream().map(ArtifactOwnershipStore.Pull::fresh).toList());assertFalse(wild.purchase(op(),player,choices("other"),"item:shard").getFirst().fresh());}
 @Test void retrySameOperationDoesNotGrantOrMailTwice()throws Exception{String operation=op();var result=school.purchase(operation,player,choices("test","test"),"item:shard");assertEquals(result,wild.purchase(operation,player,choices("different"),"item:shard"));assertEquals(Set.of("test"),school.owned(player));assertEquals(1,school.pendingDeliveries().size());}
 @Test void grantRevokeResetAgreeAcrossServers()throws Exception{school.set(player,"a",true);assertEquals(Set.of("a"),wild.owned(player));wild.set(player,"a",false);assertTrue(school.owned(player).isEmpty());school.set(player,"a",true);school.set(player,"b",true);wild.reset(player);assertTrue(school.owned(player).isEmpty());}
 @Test void oldPurchaseRetryCannotResurrectRevokedOwnership()throws Exception{String operation=op();school.purchase(operation,player,choices("test"),"item:shard");wild.set(player,"test",false);school.purchase(operation,player,choices("test"),"item:shard");assertTrue(wild.owned(player).isEmpty());}
 @Test void unionMigrationIsIdempotentAndNeverReimportsAfterRevoke()throws Exception{String sha="a".repeat(64);assertFalse(school.migrationComplete());assertTrue(school.migrate("school-v1",sha,Map.of(player,Set.of("a","shared"))));assertTrue(wild.migrate("wild-v1",sha,Map.of(player,Set.of("b","shared"))));assertTrue(school.migrationComplete());assertEquals(Set.of("a","b","shared"),school.owned(player));wild.set(player,"shared",false);assertFalse(school.migrate("school-v1",sha,Map.of(player,Set.of("a","shared"))));assertFalse(wild.migrate("wild-v1",sha,Map.of(player,Set.of("b","shared"))));assertEquals(Set.of("a","b"),school.owned(player));}
 @Test void changedMigrationInputRejectedAfterCompletion()throws Exception{school.migrate("school-v1","a".repeat(64),Map.of());assertThrows(IllegalStateException.class,()->school.migrate("school-v1","b".repeat(64),Map.of()));}
 @Test void duplicateMailRemainsPendingUntilAcknowledged()throws Exception{school.purchase(op(),player,choices("a","a"),"item:shard");var row=school.pendingDeliveries().getFirst();assertEquals("item:shard",row.item());assertEquals(2,row.amount());assertEquals(List.of(row),wild.pendingDeliveries());wild.delivered(row);school.delivered(row);assertTrue(school.pendingDeliveries().isEmpty());}
 @Test void unavailableDatabaseCannotEraseExistingOwnership()throws Exception{school.set(player,"a",true);var offline=new ArtifactOwnershipStore(()->{throw new SQLException("offline");});assertThrows(SQLException.class,()->offline.set(player,"a",false));assertThrows(SQLException.class,()->offline.purchase(op(),player,choices("b"),"item:shard"));assertEquals(Set.of("a"),wild.owned(player));}
 @Test void journalRetainsPaidRequestDuringOutageAndReplaysExactlyOnce()throws Exception{var journal=new ArtifactPurchaseJournal(temp);var request=new ArtifactPurchaseJournal.Purchase(op(),player,choices("a","a"),"item:shard");journal.prepare(request);journal.paid(request);var offline=new ArtifactOwnershipStore(()->{throw new SQLException("offline");});assertThrows(SQLException.class,()->offline.purchase(request.operation(),player,request.choices(),request.shardItem()));assertEquals(1,new ArtifactPurchaseJournal(temp).paid().size());var result=school.purchase(request.operation(),player,request.choices(),request.shardItem());assertEquals(result,wild.purchase(request.operation(),player,request.choices(),request.shardItem()));journal.remove(request.operation());assertTrue(journal.paid().isEmpty());assertEquals(1,school.pendingDeliveries().size());}
 @Test void unconfirmedDebitIsQuarantinedNotAutoGranted()throws Exception{var journal=new ArtifactPurchaseJournal(temp);journal.prepare(new ArtifactPurchaseJournal.Purchase(op(),player,choices("a"),"item:shard"));assertEquals(1,journal.uncertain());assertTrue(journal.paid().isEmpty());}
 @Test void migrationRejectsNegativeExpiringContextualAndGroupNodes()throws Exception{String prefix="user\t"+player+"\tmagiccodex.artifact.own.a\t";for(String row:List.of(prefix+"false\t0\t",prefix+"true\t1\t",prefix+"true\t0\td29ybGQ:dGVzdA","group\tdefault\tmagiccodex.artifact.own.a\ttrue\t0\t",prefix.replace("own.a","own.*")+"true\t0\t")){Path p=temp.resolve(op()+".tsv");Files.writeString(p,row);assertThrows(Exception.class,()->ArtifactOwnershipMigration.read(p));}}
 @Test void migrationAcceptsOnlyExplicitPermanentUserOwnership()throws Exception{Path p=temp.resolve("input.tsv");Files.writeString(p,"user\t"+player+"\tmagiccodex.artifact.own.a\ttrue\t0\t\n");assertEquals(Map.of(player,Set.of("a")),ArtifactOwnershipMigration.read(p));}
 @Test void operatorTemporaryAccessNeverBecomesPermanentOwnership()throws Exception{var virtual=List.of(new ArtifactOwnershipStore.Choice("a",0,2,true));assertFalse(school.purchase(op(),player,virtual,"item:shard").getFirst().fresh());assertTrue(wild.owned(player).isEmpty());school.set(player,"a",true);wild.set(player,"a",false);assertFalse(school.purchase(op(),player,virtual,"item:shard").getFirst().fresh());assertTrue(wild.owned(player).isEmpty());assertTrue(wild.purchase(op(),player,choices("a"),"item:shard").getFirst().fresh());}
 @Test void pollReadsAllOnlinePlayersWithOneConnection()throws Exception{UUID other=UUID.randomUUID(),empty=UUID.randomUUID();school.set(player,"a",true);school.set(player,"b",true);school.set(other,"c",true);school.set(other,"d",false);school.purchase(op(),player,choices("a"),"item:shard");
  var opened=new java.util.concurrent.atomic.AtomicInteger();var counting=new ArtifactOwnershipStore(()->{opened.incrementAndGet();return DriverManager.getConnection(url);});
  var poll=counting.poll(List.of(player,other,empty));assertEquals(1,opened.get());
  assertEquals(Map.of(player,Set.of("a","b"),other,Set.of("c"),empty,Set.of()),poll.owned());assertEquals(school.pendingDeliveries(),poll.deliveries());
  for(UUID id:List.of(player,other,empty))assertEquals(school.owned(id),poll.owned().get(id));
  assertTrue(counting.poll(List.of()).owned().isEmpty());}
}
